/* ไอคอนขนาดกำหนดเองสำหรับหัวข้อกล่อง/ป้าย — ใช้ currentColor เสมอ จะได้เปลี่ยนสีตามข้อความรอบ ๆ เอง */
const icx=(n,size,cls)=>`<svg class="icx ${cls||''}" width="${size||16}" height="${size||16}" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.9">${ICON[n]||''}</svg>`;
const ic=(n,c)=>`<svg fill="none" viewBox="0 0 24 24" stroke="${c}">${ICON[n]}</svg>`;

/* ===== Round 15 (hardening 20/07 — XSS): esc() ห่อทุกค่าที่มาจากผู้ใช้/Dataverse text field ก่อน render เข้า innerHTML
   ใช้ได้ทั้ง text content และ attribute value (quoted ด้วย ") เพราะ escape ครบ &<>"' (มาตรฐาน HTML entity encoding เดียวกันปลอดภัยทั้ง 2 บริบท)
   ‼️ ห้าม escape ค่า enum ระบบ (status/priority) หรือ id/GUID/label ที่เราคุมเอง — โฟกัสเฉพาะ title/details/teamNote/reason/requester/who/filename/decisionUse/ticket/deliverylink ตามบรีฟ */
function esc(s){
  return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
/* escape เฉพาะค่าที่ฝังใน inline data-drs-onclick="...('VALUE')" (ชื่อสมาชิกทีม — Dataverse text field เดียวกับ "who" แต่บริบทเป็น JS string literal ชั้นใน ไม่ใช่แค่ HTML)
   ต้อง JS-escape (backslash/quote) ก่อน แล้วค่อย esc() ทับอีกชั้นเป็น HTML-attribute — ลำดับสำคัญ: HTML-decode เกิดก่อน JS parse เสมอ ทำสลับลำดับไม่ได้ */
/* ‼️ R260 (agent QA จับ XSS จริงได้ 11/08): เดิม 4 จุดของ openPeopleCard ใช้ esc(who).replace(/'/g,"&#39;")
   ซึ่ง "ไม่พอ" เพราะเบราว์เซอร์ HTML-decode &#39; กลับเป็น ' ก่อน parse onclick เป็น JS -> break out ออกจาก string ได้จริง
   (ชื่อสมาชิกทีมตั้งได้อิสระจากหน้าจัดการทีม = payload เข้าระบบได้) -> ทุกจุดต้องผ่าน escJsAttr เท่านั้น */
function escJsAttr(s){
  return esc(String(s??"").replace(/\\/g,"\\\\").replace(/'/g,"\\'"));
}

/* ============================================================================
   R354 (พี่ปอนด์สั่ง 27/08 หลัง user ส่ง UI Fix List มา): ระบบ 2 ภาษา ไทย / English
   ----------------------------------------------------------------------------
   หลักการ (ห้ามเพี้ยน — ถ้าพลาดข้อใดข้อหนึ่ง ระบบจะพังเงียบทั้งบอร์ด/ตัวกรอง/สี):
   ‼️ ① "ภาษาไทย" ยังเป็น canonical key ของ logic เหมือนเดิมทุกจุด (d.status/d.pri/d.requestType/d.region)
        i18n ชั้นนี้เป็น "ชั้นแสดงผล" ล้วน ไม่แตะค่าที่เทียบใน logic 60 จุด และไม่แตะ payload ที่ PATCH ลง Dataverse
        -> เปลี่ยนภาษาแล้ว การกรอง/เรียง/สี/สิทธิ์/การบันทึก ต้องทำงานเหมือนเดิมเป๊ะ
   ‼️ ② key ที่ไม่มีในคลังคำแปล = ไม่แตะ element นั้นเลย (คงข้อความเดิมบนจอ) ไม่ใช่โชว์ชื่อ key
   ‼️ ③ ทุกครั้งที่ render ใหม่ด้วย innerHTML ต้องเรียก applyLang() ต่อท้าย ไม่งั้น attribute หายไปพร้อม DOM เก่า
   ‼️ ④ CSV export "เป็นอังกฤษเสมอ" ไม่ขึ้นกับสวิตช์นี้ (พี่ปอนด์เคาะ 27/08 — ไฟล์ export เอาไปต่อ Power BI ต้องนิ่ง)
   ============================================================================ */
const LANG_DEFAULT="th";
let LANG=LANG_DEFAULT;

/* ---- คำแปลค่าที่มาจาก Dataverse (FormattedValue เป็นไทย) — ใช้ทั้งป้ายบนจอและ CSV ----
   ‼️ key ต้องเป็นข้อความไทยตรงตัวที่ Dataverse ส่งกลับมาเป๊ะ (ดู STATUS_VALUE/PRI_VALUE/REQTYPE_VALUE ด้านบน)
   ‼️ ห้าม rename option label ฝั่ง Dataverse เป็นอังกฤษเพื่อ "จบทีเดียว" — Canvas app อ้าง enum ไทยตรง ๆ
      ('Status (Data Requests)'.'รอรับงาน' ดู CANVAS_BUILD_SPEC.md:143) จะพังพร้อมกัน 3 ระบบ */
const STATUS_EN={"รอรับงาน":"Awaiting Pickup","รอคิว":"Queued","กำลังทำ":"In Progress","รอข้อมูล":"Awaiting Info","ส่งมอบแล้ว":"Delivered","ปิดงาน":"Closed","ยกเลิก":"Cancelled"};
const PRI_EN={"ปกติ":"Normal","ด่วน":"Urgent","ด่วนมาก":"Critical"};
/* ‼️ ชุดนี้คือคำแปลของ "ประเภทงาน 6 ตัวเดิมที่มีอยู่จริงใน Dataverse ตอนนี้" (dr_requesttype 121900000-121900005)
   ยังไม่ใช่ชุดใหม่ 6 ตัวที่ user ขอ (Bug Fix / Data Discrepancy ฯลฯ) — ชุดใหม่ต้องเพิ่ม option ใน Dataverse ก่อน
   ไม่งั้นตัวกรอง/SLA มาตรฐาน (dr_setting team_config.sla ที่ผูก key เป็น label ไทย) จะกำพร้าเงียบ ๆ */
/* R356: canonical เป็นอังกฤษแล้ว -> ตารางนี้แปลกลับเป็นไทยสำหรับโหมดไทย (ทิศทางกลับกับของเดิม)
   ‼️ รวมป้ายไทย "ชุดเก่า" ไว้ด้วย เผื่อ record เก่าที่อ่านมาแล้วยังไม่ถูก map (กันคำหายบนจอ) */
const REQTYPE_TH={
  "Bug Fix / Data Discrepancy":"แก้บั๊ก / ข้อมูลไม่ตรง",
  "Dashboard Maintenance / Update":"ดูแล / อัปเดต Dashboard",
  "New Dashboard / Report Setup":"ทำ Dashboard / รายงานใหม่",
  "Automation":"งานอัตโนมัติ (Automation)",
  "Data Migration":"ย้าย / ดึงข้อมูล",
  "Complex Logic Development":"พัฒนา Logic ซับซ้อน",
  "Other":"อื่น ๆ"
};
const REGION_EN={"อื่น ๆ (Other)":"Other"};   // REGIONS ที่เหลือเป็นอังกฤษอยู่แล้ว (R1 (BMA West) ฯลฯ)

/* แปลค่าจาก Dataverse -> ภาษาที่ต้องการ · lang ว่าง = ใช้ LANG ปัจจุบัน · ไม่รู้จักค่า = คืนค่าเดิม (ไม่ทำหาย) */
function statusText(v,lang){ return ((lang||LANG)==="en"&&STATUS_EN[v])?STATUS_EN[v]:(v||""); }
function priText(v,lang){    return ((lang||LANG)==="en"&&PRI_EN[v])?PRI_EN[v]:(v||""); }
/* R356: canonical = อังกฤษ · โหมดไทยแปลผ่าน REQTYPE_TH · ค่าเก่าที่ยังเป็นไทยให้ map เป็น canonical ก่อน */
function reqtypeText(v,lang){
  if(!v) return "";
  const canon=REQTYPE_VALUE[v]!==undefined?v:(REQTYPE_LEGACY[v]||v);
  /* ‼️ R363 (พี่ปอนด์พลิกสเปค 02/09 17:00 "โหมดไทยต้องแสดงชื่อไทย" — ยกเลิก R361d "อังกฤษทุกโหมด" ที่ลองแล้วไม่เอา):
     โหมดไทย = แปลผ่าน REQTYPE_TH กลับมาเป็นไทย (7 ชื่อ) · โหมด EN = canonical อังกฤษเหมือนเดิมทุกตัวอักษร (ไม่เปลี่ยน)
     Dataverse label/CSV export ยังคง canonical อังกฤษเสมอ (ผู้เรียกส่ง lang='en' ตรง ๆ ไม่ผ่านจุดนี้) */
  return ((lang||LANG)==="en") ? canon : (REQTYPE_TH[canon]||canon);
}
function regionText(v,lang){ return ((lang||LANG)==="en"&&REGION_EN[v])?REGION_EN[v]:(v||""); }

/* ---- R365 (พี่ปอนด์ส่งภาพ Change history บน DEV 03/09 "ยังมีภาษาไทยอยู่") : ประวัติการเปลี่ยนแปลง 2 ภาษา ----
   ‼️ log ถูกเขียนลง dr_activity เป็น "ไทย canonical" ตอนเกิดเหตุ และห้ามเปลี่ยนสิ่งที่เขียน:
      ① record เก่าทั้งระบบเป็นไทยอยู่แล้ว (แปลตอนเขียนใหม่ = ประวัติปนสองภาษาถาวร)
      ② requesterChangeFromLog() (R346) อ่าน a==="เปลี่ยนผู้แจ้ง" ตรง ๆ — เปลี่ยนคำที่เขียน = ป้าย ⚠ ผู้แจ้งใหม่พังเงียบ
   -> แปล "ตอนแสดงผล" เท่านั้น และเฉพาะส่วนที่ระบบสร้างเอง (คำกริยา/ป้ายสถานะ/คำเชื่อม/คำนำหน้าบทบาท)
      ข้อความที่คนพิมพ์เอง (ข้อความถึงผู้แจ้ง/เหตุผลยกเลิก/ชื่อคน/อีเมล) ไม่แตะเลย */
const ACT_ACTION_EN={
  "เปลี่ยนสถานะ":"Change status",
  "รับงานนี้":"Pick up task",
  "เปลี่ยนผู้รับผิดชอบ":"Change assignee",
  "เปลี่ยนผู้แจ้ง":"Change requester",
  "แก้ข้อความถึงผู้แจ้ง":"Edit message to requester",
  "เพิ่มบันทึกภายในทีม":"Add internal note",
  "บันทึกข้อความจากแชทเข้าโน้ตทีม":"Save chat message to team note",
  "ลบข้อความถาวร":"Delete message permanently",   // R381
  "แก้วันที่ของงาน":"Edit task dates",   // R382
  "แก้รายละเอียดงาน":"Edit task details",   // R403 (C7)
  "เลื่อนกำหนดส่ง":"Change due date"   /* ‼️ ตายไปแล้วในโค้ด (R243 รื้อการลากบนปฏิทิน) แต่ record เก่าที่ TRUE/DEV ยังมีบรรทัดนี้อยู่ — ต้องแปลให้ด้วย */
};
/* วันที่ไทยในรายละเอียดของ log เก่า ("24 ก.ค.") = ข้อมูลที่บันทึกไว้ตอนนั้น ปล่อยไว้ตามเดิม แปลได้แค่คำว่า "ไม่มีกำหนด" */
const ACT_WORD_EN={"ไม่มี":"None","(ว่าง)":"(empty)","(ลบข้อความ)":"(message removed)","ไม่มีกำหนด":"No due date",
  "ชื่องาน":"Title","รายละเอียด":"Details","เอาไปใช้ทำอะไร":"Purpose","ความสำคัญ":"Priority","ภาค / ทีม":"Department / Team","ประเภทงาน":"Task Type","ลิงก์แนบ":"Links"};   // R403 (C7)
function actActionText(a){ return (LANG==="en"&&ACT_ACTION_EN[a])?ACT_ACTION_EN[a]:(a||""); }
/* คนทำ: โหมด model = ชื่อผู้ใช้จริงจาก Xrm (ห้ามแตะ) · โหมดทดสอบ local = "ทีม (อีเมล)" -> แปลเฉพาะคำนำหน้าบทบาท */
function actByText(by){
  const t=String(by||"");
  return LANG==="en" ? t.replace(/^(แอดมิน|ทีม|ผู้แจ้ง)(?=\s*\(|$)/,m=>roleText(m)) : t;
}
/* ค่าหนึ่งช่องในรายละเอียด: ป้ายสถานะ หรือคำแทนค่าว่าง — ที่เหลือ (ชื่อคน/อีเมล) คืนเดิมไม่แตะ */
function actValueText(v){
  const t=String(v||"").trim();
  if(STATUS_EN[t]||ACT_WORD_EN[t]) return STATUS_EN[t]||ACT_WORD_EN[t];
  const m=t.match(/^([^:]{1,40}):\s*(.+)$/);   // R403 (ล่าบั๊ก B21): "Delivered Date: (ว่าง)" มีป้ายนำหน้า แปลส่วนค่า
  return m?`${m[1]}: ${STATUS_EN[m[2]]||ACT_WORD_EN[m[2]]||m[2]}`:t;
}
function actDetailText(action,detail){
  /* R398: ห้ามจุดกลางคั่นข้อความบนจอ (กฎพี่ปอนด์ 09/09) log เก่าเก็บ " · " ไว้แล้ว แก้ตอนแสดงเป็น ", " ส่วน log ใหม่เขียน ", " ตั้งแต่ต้น
     ตัดช่วงด้วย ", " เฉพาะหน้าคำที่ระบบเขียนเอง (มอบให้ / สถานะคงเดิม) ชื่อคนที่มีจุลภาคจึงไม่ถูกหั่น */
  const s=action==="แก้ข้อความถึงผู้แจ้ง"?String(detail||""):String(detail||"").replace(/ · /g,", ").replace(/\b(\d{4})-(\d{2})-(\d{2})\b/g,"$3/$2/$1");   // R419s วันที่บนจอ dd/mm/yyyy (log ยังเก็บ yyyy-mm-dd)
  if(LANG!=="en"||!s) return s;
  if(action==="แก้ข้อความถึงผู้แจ้ง") return ACT_WORD_EN[s.trim()]||s;
  if(action==="แก้รายละเอียดงาน") return s.split(", ").map(w=>ACT_WORD_EN[w.trim()]||w).join(", ");   // R403 (C7): รายชื่อช่องที่แก้   // เนื้อความคนพิมพ์เอง — แปลได้แค่คำแทน "ลบข้อความ"
  let reason="";
  const core=s.replace(/\s*\(ยกเลิกงาน:\s*([\s\S]*?)\)\s*$/,(m,r)=>{ reason=r; return ""; })   // เหตุผลยกเลิก = คนพิมพ์เอง
    .split(/, (?=มอบให้|สถานะคงเดิม)/).map(seg=>{
      const t=seg.trim();
      let m=t.match(/^มอบให้\s+([\s\S]+)$/);          if(m) return "assigned to "+m[1];
      m=t.match(/^สถานะคงเดิม\s*"([^"]*)"$/);          if(m) return 'status unchanged "'+actValueText(m[1])+'"';
      if(t.includes("→")) return t.split("→").map(actValueText).join(" → ");
      return actValueText(t);
    }).join(", ");
  return reason?core+" (Cancel reason: "+reason+")":core;
}

