let ATTACH_CACHE={}; // model mode เท่านั้น: recordId -> array meta (annotationid,filename,mimetype,filesize,[blobUrl]) · undefined = ยังไม่โหลด

const TINY_PNG_B64="iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAeElEQVR42mP8//8/Ay0BEwONAQuEeqwiTXWjZe88pYcPRi0YARawkJrsSE3WLKQajSxCjDVMZJhOjBSxFhA0gqCCAU1FxIQAQWWjGY0iC4jMTfiVDXQQEfQEQQVMlIQAMWHIQnwo07Cwo6RhMJrRRi2gHDAO+dY1AF1hKGWUnNBhAAAAAElFTkSuQmCC";
