function attachSizeLabel(bytes){
  if(bytes==null) return "";
  if(bytes<1024) return bytes+" B";
  if(bytes<1024*1024) return (bytes/1024).toFixed(1)+" KB";
  return (bytes/1024/1024).toFixed(1)+" MB";
}
/* undefined = model mode ที่ยังไม่เคยโหลด (โหลดครั้งแรกตอนเปิด modal เท่านั้น — ไม่พรีโหลดทุกใบกัน N+1 query) */
function getAttachments(id){
  if(RUN!=="model") return MOCK_ATTACHMENTS[id]||(MOCK_ATTACHMENTS[id]=[]);
  return ATTACH_CACHE[id];
}
