function generalAttachSubject(name){ return String(name||"")==="delivery"?"delivery (ไฟล์แนบ)":name; }
function getGeneralAttachments(id){ const l=getAttachments(id); return l===undefined?undefined:l.filter(a=>a.subject!=="delivery"); }
