  R422_GT={sel:false,az:false,pick:[],i:0,items:[]};
  const s=document.createElement("div"); s.className="r422-gt-scrim"; s.id="r422-gt";
  s.innerHTML=`<div class="r422-gt" role="dialog" aria-label="${esc(tr("r422.goto","ไปที่คอลัมน์"))}"><div class="in"><svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" d="M21 21l-5.2-5.2M17 10.5a6.5 6.5 0 11-13 0 6.5 6.5 0 0113 0z"/></svg>
    <input id="r422-gq" placeholder="${esc(tr("r422.gotoPh","ชื่อคอลัมน์ หรือเลขตั๋ว"))}" autocomplete="off"><button type="button" class="gb" id="r422-gsel">${esc(tr("r422.select","เลือก"))}</button><button type="button" class="gb" id="r422-gaz">A↓Z</button></div>
    <div class="ls" id="r422-gls"></div><div class="gft" id="r422-gft" hidden><button type="button" id="r422-gapply" disabled></button></div></div>`;
  document.body.appendChild(s);
