  let best=null; ths.forEach((t,i)=>{ const b=t.getBoundingClientRect(); [[b.left,i],[b.right,i+1]].forEach(([x,ix])=>{ if(ix<lockN) return; const d=Math.abs(e.clientX-x); if(!best||d<best.d) best={d,x,ix}; }); });
  if(!best) return; R422_DRAG.to=best.ix; R422_DRAG.keys=ths.map(t=>t.dataset.col);
